// Entrada de la tool: una consulta en lenguaje natural (la arma el agente).
// Calcula los flags de nicho (guard del RPC) por regex sobre la consulta.
const q = String($json.consulta || $json.query || $json.input || '').trim();
const norm = (s) => s.normalize('NFC').toLowerCase()
  .replace(/[áéíóúü]/g, (c) => ({ 'á':'a','é':'e','í':'i','ó':'o','ú':'u','ü':'u' }[c]))
  .replace(/ñ/g, 'n');
const v = norm(q);
return [{ json: {
  texto: q,
  medicina: /medicin/.test(v),
  inmobiliarias: /inmobiliari|inmueble/.test(v),
} }];

// Trunca el embedding a 1536 dims (Matryoshka) y lo normaliza L2 → literal ::vector.
const emb = $json.data && $json.data[0] && $json.data[0].embedding;
if (!Array.isArray(emb)) {
  throw new Error('Respuesta de embeddings sin vector: ' + JSON.stringify($json).slice(0, 200));
}
const DIMS = 1536;
if (emb.length < DIMS) throw new Error('Embedding de ' + emb.length + ' dims (< ' + DIMS + ').');
const t = emb.slice(0, DIMS);
const norma = Math.sqrt(t.reduce((s, x) => s + x * x, 0)) || 1;
const vector = '[' + t.map((x) => x / norma).join(',') + ']';
const prep = $('Preparar').first().json;
return [{ json: {
  vector,
  medicina: prep.medicina,
  inmobiliarias: prep.inmobiliarias,
} }];

// Devuelve los candidatos como texto para el agente (observación de la tool).
const rows = $input.all().map((i) => i.json).filter((r) => r && r.nombre_canonico);
const lista = rows.length
  ? rows.map((r, i) =>
      (i + 1) + '. ' + r.nombre_canonico + (r.rubro ? ' (rubro: ' + r.rubro + ')' : '') + '\n' + r.chunk_text
    ).join('\n\n')
  : 'No se encontraron productos que coincidan con esa consulta.';
return [{ json: { response: lista } }];
